<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\User; use Illuminate\Http\Request; class UserController extends Controller { public function index(Request $r){$q=User::with(['profile','educationDetail','professionalDetail'])->where('role','customer'); if($r->filled('status'))$q->where('status',$r->status); if($r->filled('gender'))$q->where('gender',$r->gender); if($r->filled('search'))$q->where(fn($x)=>$x->where('name','ilike','%'.$r->search.'%')->orWhere('email','ilike','%'.$r->search.'%')->orWhere('phone','ilike','%'.$r->search.'%')); $users=$q->latest()->paginate(20)->withQueryString(); return view('admin.users.index',compact('users'));} public function show(User $user){$user->load(['profile','familyDetail','educationDetail','professionalDetail','religiousDetail','lifestyleDetail','partnerPreference','photos']);return view('admin.users.show',compact('user'));} public function approve(User $user){$user->update(['status'=>'approved']);return back()->with('success','Profile approved.');} public function reject(User $user){$user->update(['status'=>'rejected']);return back()->with('success','Profile rejected.');} public function toggle(User $user){$user->update(['is_active'=>!$user->is_active]);return back()->with('success','User status updated.');} public function destroy(User $user){$user->delete();return redirect()->route('admin.users')->with('success','User deleted.');} }
